from fastapi import APIRouter, HTTPException, Query
from ..database import db_manager

router = APIRouter(tags=["Security Alerts"])

@router.get("/alerts")
def list_alerts(
    limit: int = 50,
    offset: int = 0
):
    """Retrieves security alerts generated by the detection engine."""
    limit_val = int(getattr(limit, "default", limit)) if not isinstance(limit, int) else limit
    offset_val = int(getattr(offset, "default", offset)) if not isinstance(offset, int) else offset
    alerts = db_manager.get_alerts(limit=limit_val, offset=offset_val)
    return {"count": len(alerts), "alerts": alerts}
